//! CLDR plural categories, from rules generated by `generate/plurals.mjs`. The compiled catalogue's
//! `f.p` runs the same rules as JS (`formatter`), so a page and a toast pick the same case.

use crate::message::PluralCategory;

#[path = "plural/rules.rs"]
mod rules;

pub use rules::CLDR_VERSION;

/// CLDR's plural operands of a number as its shortest decimal shows it (`1.5`: v 1, f 5).
pub(crate) struct Operands {
    n: f64,
    i: u64,
    v: u64,
    f: u64,
    t: u64,
    e: u64,
}

impl Operands {
    pub(crate) fn of(value: f64) -> Self {
        let n = value.abs();
        // Rust prints a float's shortest round-trip digits without an exponent, as the JS side does.
        let text = format!("{n}");
        let fraction = text.split_once('.').map_or("", |(_, f)| f);
        let trimmed = fraction.trim_end_matches('0');
        let digits = |s: &str| s.get(..18).unwrap_or(s).parse::<u64>().unwrap_or(0);
        Self {
            n,
            i: n.trunc() as u64,
            v: fraction.len() as u64,
            f: digits(fraction),
            t: digits(trimmed),
            e: 0,
        }
    }
}

/// The rule set for a BCP 47 tag: the whole tag if CLDR has one for it (`pt-PT`), else its language.
fn rule(tag: &str, ordinal: bool) -> Option<usize> {
    let find = |id: &str| {
        if ordinal {
            rules::ordinal_rule(id)
        } else {
            rules::cardinal_rule(id)
        }
    };
    let mut subtags = tag.split(['-', '_']);
    let language = subtags.next()?.to_ascii_lowercase();
    let region_or_script = subtags.next().map(|s| match s.len() {
        2 => s.to_ascii_uppercase(),
        _ => s[..1].to_ascii_uppercase() + &s[1..].to_ascii_lowercase(),
    });
    region_or_script
        .and_then(|second| find(&format!("{language}-{second}")))
        .or_else(|| find(&language))
}

/// The plural category of `value` in `tag`'s language; `other` for a language CLDR does not know.
pub fn category(tag: &str, ordinal: bool, value: f64) -> PluralCategory {
    match rule(tag, ordinal) {
        Some(index) if value.is_finite() => rules::apply(index, &Operands::of(value)),
        _ => PluralCategory::Other,
    }
}

/// JS for the compiled catalogue's `f.p`: `plural(tag, ordinal, value)` with the rules of `languages`
/// only, so a bundle carries a few hundred bytes per language it ships.
pub fn js(languages: &[&str]) -> String {
    let mut used = std::collections::BTreeMap::new();
    let mut cardinal = Vec::new();
    let mut ordinal = Vec::new();
    for tag in languages {
        for (is_ordinal, map) in [(false, &mut cardinal), (true, &mut ordinal)] {
            if let Some(index) = rule(tag, is_ordinal) {
                let next = used.len();
                let slot = *used.entry(index).or_insert(next);
                map.push(format!(
                    "{}: {slot}",
                    serde_json::to_string(tag).unwrap_or_default()
                ));
            }
        }
    }
    let mut ordered: Vec<_> = used.into_iter().collect();
    ordered.sort_by_key(|(_, slot)| *slot);
    let functions: Vec<_> = ordered
        .iter()
        .map(|(index, _)| rules::JS_RULES[*index])
        .collect();
    format!(
        r#"const pluralRules = [{}];
const cardinalRules = {{ {} }};
const ordinalRules = {{ {} }};
{}
function plural(tag, ordinal, value) {{
  const rules = ordinal ? ordinalRules : cardinalRules;
  // The whole tag if it has its own rules (pt-PT), else its language (en-US reads en).
  let rule = rules[tag];
  if (rule === undefined) rule = rules[tag.split(/[-_]/)[0].toLowerCase()];
  return rule === undefined || !Number.isFinite(value) ? 'other' : pluralRules[rule](operands(value));
}}
"#,
        functions.join(",\n  "),
        cardinal.join(", "),
        ordinal.join(", "),
        rules::JS_OPERANDS,
    )
}

#[cfg(test)]
mod tests {
    use super::*;

    const CASES: &str = include_str!("../tests/plural-cases.json");

    fn name(category: PluralCategory) -> &'static str {
        match category {
            PluralCategory::Zero => "zero",
            PluralCategory::One => "one",
            PluralCategory::Two => "two",
            PluralCategory::Few => "few",
            PluralCategory::Many => "many",
            PluralCategory::Other => "other",
        }
    }

    #[test]
    fn every_shared_case_picks_cldr_s_category() {
        let table: serde_json::Value = serde_json::from_str(CASES).unwrap();
        let cases = table["cases"].as_array().unwrap();
        assert!(cases.len() > 200);
        for case in cases {
            let language = case["language"].as_str().unwrap();
            let ordinal = case["type"] == "ordinal";
            let value = case["value"].as_f64().unwrap();
            assert_eq!(
                name(category(language, ordinal, value)),
                case["category"].as_str().unwrap(),
                "{language} {} {value}",
                case["type"]
            );
        }
    }

    #[test]
    fn a_region_with_its_own_rules_wins_over_its_language() {
        // CLDR gives European Portuguese its own `one`: 0 is `one` in pt, `other` in pt-PT.
        assert_eq!(category("pt", false, 0.0), PluralCategory::One);
        assert_eq!(category("pt-PT", false, 0.0), PluralCategory::Other);
        assert_eq!(category("de-AT", false, 1.0), PluralCategory::One);
        assert_eq!(category("xx", false, 1.0), PluralCategory::Other);
    }

    #[test]
    fn the_js_table_carries_only_the_languages_asked_for() {
        let one = js(&["de"]);
        let three = js(&["de", "ru", "ar"]);
        assert!(one.contains("\"de\": 0"));
        assert!(!one.contains("\"ru\""));
        assert!(three.len() > one.len());
        // German and Dutch share both rule sets; the table holds each once.
        assert_eq!(
            js(&["de", "nl"]).matches("o => {").count(),
            js(&["de"]).matches("o => {").count()
        );
    }
}
